  "quiz": [
    {
      "id": "q1",
      "q": "二十年前死在雾见屋古井里的女中小菊，留下的那个孩子后来怎样了？",
      "options": [
        {
          "key": "A",
          "text": "被横滨的亲戚接走了"
        },
        {
          "key": "B",
          "text": "被云隐寺的老住持收养，后来出了家"
        },
        {
          "key": "C",
          "text": "留在雾见屋当了板场学徒"
        },
        {
          "key": "D",
          "text": "送进了东京的孤儿院"
        }
      ],
      "answer": "B",
      "clue": "ao_well_4",
      "explain": "送火台湿灰里那角信纸盖着云隐寺的寺印，写着「你母亲」「菊」「井盖」，是写给小菊之子的信；何了尘客房经本里那张「菊与树」的旧照片也对得上：那个孩子被云隐寺收养，就是如今的住持。"
    },
    {
      "id": "q2",
      "q": "大广间壁龛里空着的第十只伊万里盘子，当年是怎么碎的？",
      "options": [
        {
          "key": "A",
          "text": "女中小菊失手打碎"
        },
        {
          "key": "B",
          "text": "地震时从架上跌落"
        },
        {
          "key": "C",
          "text": "被人用硬物一下下敲碎"
        },
        {
          "key": "D",
          "text": "搬家时被箱子压碎"
        }
      ],
      "answer": "C",
      "clue": "ao_hall_4",
      "explain": "壁橱里那包「井边拾得」的碎瓷断口平整，背面有一圈圈被硬物敲击的崩痕，不是失手摔碎的样子；魏长灯的旧事也说明，盘子是甄鹤年事后用锤子敲碎撒在井边的。"
    },
    {
      "id": "q3",
      "q": "昭和四十年盂兰盆那一夜，把古井木盖盖上的人是谁？",
      "options": [
        {
          "key": "A",
          "text": "甄鹤年"
        },
        {
          "key": "B",
          "text": "魏长灯"
        },
        {
          "key": "C",
          "text": "云隐寺的老住持慧明"
        },
        {
          "key": "D",
          "text": "民俗学者吴文渊"
        }
      ],
      "answer": "B",
      "clue": "ao_wei_4",
      "explain": "帐场后间佛龛下那张昭和五十年的护摩札背面写着「那晚盖上井盖的是我」，这是魏长灯向慧明住持忏悔后留下的。"
    },
    {
      "id": "q4",
      "q": "让雾见屋出名的《雾见屋百物语》，里面的故事最早是谁采录的？",
      "options": [
        {
          "key": "A",
          "text": "甄鹤年"
        },
        {
          "key": "B",
          "text": "蓉千代"
        },
        {
          "key": "C",
          "text": "吴文渊"
        },
        {
          "key": "D",
          "text": "魏长灯"
        }
      ],
      "answer": "C",
      "clue": "ao_wu_3",
      "explain": "那本旧皮面手记扉页写着「采录，吴文渊，昭和三十九年」，是吴夜语的父亲在雾见屋住了一年多记下的，后来被甄鹤年扣作房钱抵押。"
    },
    {
      "id": "q5",
      "q": "蓉千代嫁进雾见屋之前，是在哪里做事的？",
      "options": [
        {
          "key": "A",
          "text": "热海的温泉旅馆"
        },
        {
          "key": "B",
          "text": "横滨中华街的夜总会"
        },
        {
          "key": "C",
          "text": "神户的中华料理店"
        },
        {
          "key": "D",
          "text": "东京的百货公司"
        }
      ],
      "answer": "B",
      "clue": "ao_rong_1",
      "explain": "蓉千代镜框边那张照片上，她穿着旗袍站在横滨中华街的夜来香夜总会门前；她在那里唱了十几年歌。"
    },
    {
      "id": "q6",
      "q": "大满福去年借下的那二百万日元，借据是写给谁的？",
      "options": [
        {
          "key": "A",
          "text": "横滨的一家钱庄"
        },
        {
          "key": "B",
          "text": "撒氏不动产的撒社长"
        },
        {
          "key": "C",
          "text": "甄鹤年"
        },
        {
          "key": "D",
          "text": "魏长灯"
        }
      ],
      "answer": "C",
      "clue": "ao_da_3",
      "explain": "米柜信封里夹着的那张借据写着出借人甄鹤年、金额二百万日元、昭和五十九年立；横滨钱庄的是另一笔赌债的催款单。"
    }
  ],
